import{e as t,ab as a,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [May]","description":"May 2025 updates.","frontmatter":{"title":"Monthly Updates [May]","description":"May 2025 updates.","date":"2025-05-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/may-2025.md","filePath":"posts/may-2025.md"}'),l={name:"posts/may-2025.md"};function d(h,e,f,p,m,g){const r=a("Post");return o(),n("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Made a FMHY <a href="https://redlib.fmhy.net/r/FREEMEDIAHECKYEAH/wiki/index" target="_blank" rel="noreferrer">Redlib Instance</a> + our <a href="https://searx.fmhy.net/" target="_blank" rel="noreferrer">SearXNG</a> is working again too.</p></li><li><p>Added an <a href="https://fmhy.net/gaming-tools#arpg-mmorpg-tools" target="_blank" rel="noreferrer">ARPG / MMORPG</a> section in Gaming Tools.</p></li><li><p>Added <a href="https://fmhy.net/reading#stem-resources" target="_blank" rel="noreferrer">STEM</a> + <a href="https://fmhy.net/reading#kindle-tools" target="_blank" rel="noreferrer">Kindle Tools</a> sections in Reading.</p></li><li><p>Added <a href="https://fmhy.net/video-tools#disc-utilities" target="_blank" rel="noreferrer">Disc Utilities</a> + <a href="https://fmhy.net/video-tools#video-enhancement-effects" target="_blank" rel="noreferrer">Video Enhancement / Effects</a> sections in Video Tools.</p></li><li><p>Split the Steam / Epic section into subsections: <a href="https://fmhy.net/gaming-tools#client-tools" target="_blank" rel="noreferrer">Client Tools</a>, <a href="https://fmhy.net/gaming-tools#dlc-unlock-drm-bypass" target="_blank" rel="noreferrer">DLC Unlock / DRM Bypass</a>, and <a href="https://fmhy.net/gaming-tools#steam-store" target="_blank" rel="noreferrer">Steam Store</a>.</p></li><li><p>Split the macOS section into subsections: <a href="https://fmhy.net/linux-macos#mac-video" target="_blank" rel="noreferrer">Video</a>, <a href="https://fmhy.net/linux-macos#mac-audio" target="_blank" rel="noreferrer">Audio</a>, <a href="https://fmhy.net/linux-macos#mac-images" target="_blank" rel="noreferrer">Image</a>, <a href="https://fmhy.net/linux-macos#mac-internet" target="_blank" rel="noreferrer">Internet</a>, <a href="https://fmhy.net/linux-macos#system-tools" target="_blank" rel="noreferrer">System</a>, and <a href="https://fmhy.net/linux-macos#file-tools-1" target="_blank" rel="noreferrer">File</a>.</p></li><li><p>Split PDF Tools into subsections: <a href="https://fmhy.net/file-tools#online-pdf-toolkits" target="_blank" rel="noreferrer">Online Toolkits</a>, <a href="https://fmhy.net/file-tools#offline-pdf-toolkits" target="_blank" rel="noreferrer">Offline Toolkits</a>, <a href="https://fmhy.net/file-tools#pdf-conversion-tools" target="_blank" rel="noreferrer">Conversion</a>, and <a href="https://fmhy.net/file-tools#pdf-utilities" target="_blank" rel="noreferrer">Utilities</a>.</p></li><li><p>Split Video Processing into <a href="https://fmhy.net/video-tools#processing-encoding" target="_blank" rel="noreferrer">Programs</a> and <a href="https://fmhy.net/video-tools#online-processing" target="_blank" rel="noreferrer">Online</a> sections.</p></li><li><p>Re-organized &amp; added labels to <a href="https://fmhy.net/storage#android-text-editors" target="_blank" rel="noreferrer">Android Text Editors</a>, <a href="https://fmhy.net/storage#note-taking" target="_blank" rel="noreferrer">Note-Taking</a>, and <a href="https://fmhy.net/storage#to-do-apps" target="_blank" rel="noreferrer">To-Do</a>. <a href="https://i.imgur.com/JyGeAsi.jpeg" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Re-organized &amp; added labels to <a href="https://fmhy.net/storage#ambient-sound-mixers" target="_blank" rel="noreferrer">Ambient Sound Mixers</a> and <a href="https://fmhy.net/storage#android-browsers" target="_blank" rel="noreferrer">Android Browsers</a>. <a href="https://i.imgur.com/F48u9pk.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Re-organized &amp; added labels to <a href="https://fmhy.net/storage#website-templates" target="_blank" rel="noreferrer">Website Templates</a>, <a href="https://fmhy.net/storage#wordpress-themes" target="_blank" rel="noreferrer">WordPress Themes</a>, and <a href="https://fmhy.net/video#free-w-ads" target="_blank" rel="noreferrer">YouTube Movies</a>. <a href="https://i.imgur.com/Q84jTaz.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Re-organized the <a href="https://fmhy.net/reading#manga" target="_blank" rel="noreferrer">Manga Section</a> based on <a href="https://challonge.com/lzbv9baj/" target="_blank" rel="noreferrer">Poll Results</a>. Congrats to ComicK for coming out on top.</p></li><li><p>Moved <a href="https://fmhy.net/developer-tools#website-generators" target="_blank" rel="noreferrer">Website Generators</a> out of storage, re-organized, and added labels. <a href="https://i.imgur.com/V1DWN9D.jpeg" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Moved <a href="https://fmhy.net/image-tools#_3d-models" target="_blank" rel="noreferrer">3D Modeling + CAD Sections</a> out of storage, re-organized, and added labels. <a href="https://i.imgur.com/4V41Zdx.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>All media tracking sections have now been split into Tracking / Databases and Recommendations. This applies to Streaming, Gaming, Reading, and Audio sections.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/video" target="_blank" rel="noreferrer">AnimeKai</a> in Anime Streaming. Feature-rich, huge library, fast servers. People seem to really like it, so we&#39;ve moved it to the #1 spot.</p></li><li><p>Starred both <a href="https://fmhy.net/video#drives-directories" target="_blank" rel="noreferrer">111477 + DramaSuki</a> in Drives / Directories. Both have fast speeds and lots of content.</p></li><li><p>Starred <a href="https://fmhy.net/reading#comics" target="_blank" rel="noreferrer">BatCave</a> in Comic Sites. New comic site with tracking, ratings, and a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#p2p-transfer" target="_blank" rel="noreferrer">PairDrop</a> in P2P File Transfer. Open-source, easy to use, and allows creating rooms.</p></li><li><p>Starred <a href="https://fmhy.net/reading#curated-recommendations" target="_blank" rel="noreferrer">Five Books</a> in Book Recommendations. Expert-recommended top 5 lists with lots of categories.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#curated-recommendations" target="_blank" rel="noreferrer">VideoGameCanon</a> in Game Recommendations. Game top 1,000 list that people in our server find useful.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#url-tools" target="_blank" rel="noreferrer">Mini QR</a> in URL Tools. Lets you create custom QR code art.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#productivity-trackers" target="_blank" rel="noreferrer">Table Habit</a> in Android Productivity Trackers. Open-source, updated regularly, and has a nice UI.</p></li><li><p>Starred both <a href="https://fmhy.net/storage#background-removers" target="_blank" rel="noreferrer">BGBye + Pixelcut</a> in Background Removers as they seemed to work the best.</p></li><li><p>Starred <a href="https://encyclosearch.org/" target="_blank" rel="noreferrer">EncycloSearch</a> in Encyclopedias. Combines two dozen encyclopedias into one search engine.</p></li><li><p>Starred <a href="https://fmhy.net/audio#audio-ripping-tools" target="_blank" rel="noreferrer">Exact Audio Copy</a> in Audio Ripping. Popular CD ripping tool, recommended in Redacted&#39;s interview guide.</p></li><li><p>Switched to <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">AI Studio</a> as Google&#39;s main chatbot as it works well on mobile, is less laggy, has chat history, and has less censorship than Gemini.</p></li><li><p>Added <a href="https://fmhy.net/video#free-w-ads" target="_blank" rel="noreferrer">Free-Official-YouTube-Content</a> as an index emoji in Free w/ Ads. Not a star, but we feel it&#39;s good enough to mention.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li>Removed ReVanced MMT as it&#39;s no longer maintained.</li></ul>',9))])}const u=t(l,[["render",d]]);export{b as __pageData,u as default};
